command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1"
$candidate="741c48f6239f5bc566bf75df232d1a57eee26118"
$branch="work/unc-network-metadata-sort-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network metadata fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network metadata validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network metadata candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-metadata-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "network metadata worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "network metadata diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "network metadata FAST failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "network metadata Release build failed"}
  & python -u -X utf8 .\tests\winui\test_metadata_sort_gui.py --configuration Release --force-isolated-metadata
  if($LASTEXITCODE -ne 0){throw "network metadata focused GUI failed"}
  Write-Host "NETWORK_METADATA_DIFF_CHECK=PASS"
  Write-Host "NETWORK_METADATA_FAST=PASS"
  Write-Host "NETWORK_METADATA_RELEASE_BUILD=PASS"
  Write-Host "NETWORK_METADATA_ISOLATED_GUI=PASS"
  Write-Host "NETWORK_METADATA_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
